mapper.select:
SELECT mpp.id, mpp.image_url AS imageUrl FROM missing_pet_post mpp
mpp.id < #{cursor}
ORDER BY mpp.id DESC LIMIT #{limit}

SELECT member_id
FROM missing_pet_post
