mapper.update:
UPDATE missing_pet_post
SET missing_date = #{missingDate}, missing_address = #{missingAddress}, detail = #{detail}, image_url = #{imageUrl}, latitude = #{latitude}, longitude = #{longitude}, updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}

mapper.select:
SELECT status
FROM missing_pet_post
WHERE id = #{id}

